import app from 'flarum/admin/app';
import ExtensionPage from 'flarum/admin/components/ExtensionPage';
import RecaptchaTest from './RecaptchaTest';
export default class RecaptchaPage extends ExtensionPage {
  sections(vnode) {
    const items = super.sections(vnode);
    const settings = {
      ...this.settings
    };
    for (const key in settings) {
      if (settings[key] instanceof Function) {
        settings[key] = settings[key].call(this);
      }
    }
    if (app.data.maintenanceMode) {
      items.add('maintenance', m("div", {
        className: "Alert Alert--danger"
      }, app.translator.trans('fof-recaptcha.admin.maintenance_mode_warning')), 100);
    }
    items.add('recaptcha', m(RecaptchaTest, {
      settings: settings
    }));
    items.setPriority('permissions', -1);
    return items;
  }
}
flarum.reg.add('framio-security', 'recaptcha/admin/components/RecaptchaPage', RecaptchaPage);